message.content:
{
  "css": ".trip-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 62px;
  gap: 16px;
}

.trip-header > button {
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  padding: 0;
  cursor: pointer;
}

.trip-header > button[disabled] {
  opacity: 1;
  cursor: default;
}

.trip-header > button img {
  width: 24px;
  height: 24px;
  display: block;
}

.trip-header > h1 {
  flex: 1;
  margin: 0;
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.trip-header > span {
  flex: 0 0 44px;
  width: 44px;
}"
}
